import React, { useEffect, useState } from 'react';
import api from '../../services/api';

function AdminHouses() {
  const [houses, setHouses] = useState([]);
  const [form, setForm] = useState({
    name: '',
    location: '',
    description: '',
    price: '',
    capacity: '',
    image: ''
  });
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState('');

  const fetchHouses = async () => {
    try {
      const res = await api.get('/admin/houses');
      setHouses(res.data.houses || []);
    } catch {
      setHouses([]);
    }
  };

  useEffect(() => {
    fetchHouses();
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      await api.post('/admin/houses', form);
      setForm({ name: '', location: '', description: '', price: '', capacity: '', image: '' });
      setMessage('Casa creada con éxito');
      fetchHouses();
    } catch {
      setMessage('Error al crear la casa');
    }
  };

  const handleEdit = (house) => {
    setEditId(house.id);
    setForm(house);
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await api.put(`/admin/houses/${editId}`, form);
      setMessage('Casa actualizada');
      setEditId(null);
      setForm({ name: '', location: '', description: '', price: '', capacity: '', image: '' });
      fetchHouses();
    } catch {
      setMessage('Error al actualizar la casa');
    }
  };

  const toggleAvailability = async (id) => {
    try {
      await api.put(`/admin/houses/${id}/toggle`);
      fetchHouses();
    } catch {
      setMessage('Error al cambiar disponibilidad');
    }
  };

  return (
    <div>
      <h4>Casas registradas</h4>
      <ul className="list-group mb-4">
        {houses.map((house) => (
          <li key={house.id} className="list-group-item d-flex justify-content-between align-items-start">
            <div className="me-3">
              <strong>{house.name}</strong> – {house.location} <br />
              <small>{house.description}</small><br />
              <small>💰 {house.price} € | 👥 {house.capacity}</small><br />
              <small>🖼️ {house.image}</small>
            </div>
            <div>
              <span className={`badge ${house.availability ? 'bg-success' : 'bg-secondary'} me-2`}>
                {house.availability ? 'Activa' : 'Inactiva'}
              </span>
              <button className="btn btn-sm btn-warning me-2" onClick={() => handleEdit(house)}>Editar</button>
              <button className="btn btn-sm btn-outline-dark" onClick={() => toggleAvailability(house.id)}>Cambiar estado</button>
            </div>
          </li>
        ))}
      </ul>

      <h5>{editId ? 'Editar casa' : 'Añadir nueva casa'}</h5>
      {message && <div className="alert alert-info">{message}</div>}

      <form onSubmit={editId ? handleUpdate : handleCreate}>
        <input name="name" className="form-control mb-2" placeholder="Nombre" value={form.name} onChange={handleChange} required />
        <input name="location" className="form-control mb-2" placeholder="Ubicación" value={form.location} onChange={handleChange} required />
        <textarea name="description" className="form-control mb-2" placeholder="Descripción" value={form.description} onChange={handleChange} required />
        <input type="number" name="price" className="form-control mb-2" placeholder="Precio por noche" value={form.price} onChange={handleChange} required />
        <input type="number" name="capacity" className="form-control mb-2" placeholder="Capacidad" value={form.capacity} onChange={handleChange} required />
        <input name="image" className="form-control mb-2" placeholder="Ruta de la imagen" value={form.image} onChange={handleChange} />
        <button className="btn btn-primary">{editId ? 'Actualizar' : 'Crear casa'}</button>
      </form>
    </div>
  );
}

export default AdminHouses;
